-- Substitui perguntas por Python introdutório, mantendo IDs e partidas.
BEGIN;
UPDATE public.perguntas SET enunciado='Qual função mostra uma mensagem na tela em Python?', alternativa_a='echo()', alternativa_b='print()', alternativa_c='console.log()', alternativa_d='show()', correta='B', dificuldade='facil', fonte='https://docs.python.org/3/library/functions.html#print' WHERE enunciado IN ('Qual comando é utilizado em Python para exibir uma mensagem no console?','Qual função mostra uma mensagem na tela em Python?');
UPDATE public.perguntas SET enunciado='Qual símbolo inicia um comentário de uma linha em Python?', alternativa_a='//', alternativa_b='--', alternativa_c='#', alternativa_d='/*', correta='C', dificuldade='facil', fonte='https://docs.python.org/3/reference/lexical_analysis.html#comments' WHERE enunciado IN ('Qual símbolo é utilizado para iniciar um comentário de linha única em Python?','Qual símbolo inicia um comentário de uma linha em Python?');
UPDATE public.perguntas SET enunciado='Qual é o tipo do resultado de 5 > 2?', alternativa_a='int', alternativa_b='str', alternativa_c='bool', alternativa_d='float', correta='C', dificuldade='facil', fonte='https://docs.python.org/3/library/stdtypes.html#comparisons' WHERE enunciado IN ('Qual tipo de dado é retornado pela expressão 5 > 2 em Python?','Qual é o tipo do resultado de 5 > 2?');
UPDATE public.perguntas SET enunciado='Qual é o tipo de dado do texto "Olá" em Python?', alternativa_a='int', alternativa_b='str', alternativa_c='bool', alternativa_d='float', correta='B', dificuldade='facil', fonte='https://docs.python.org/3/library/stdtypes.html#text-sequence-type-str' WHERE enunciado IN ('O que significa a sigla IA no contexto da tecnologia moderna?','Qual é o tipo de dado do texto "Olá" em Python?');
UPDATE public.perguntas SET enunciado='Qual palavra inicia a definição de uma função em Python?', alternativa_a='function', alternativa_b='func', alternativa_c='define', alternativa_d='def', correta='D', dificuldade='facil', fonte='https://docs.python.org/3/reference/compound_stmts.html#function-definitions' WHERE enunciado IN ('Qual palavra-chave é usada em Python para declarar uma função?','Qual palavra inicia a definição de uma função em Python?');
UPDATE public.perguntas SET enunciado='Qual destas opções representa uma lista em Python?', alternativa_a='[1, 2, 3]', alternativa_b='(1, 2, 3)', alternativa_c='{1, 2, 3}', alternativa_d='"1, 2, 3"', correta='A', dificuldade='facil', fonte='https://docs.python.org/3/tutorial/datastructures.html' WHERE enunciado IN ('Em Python, qual estrutura de dados é ordenada, mutável e delimitada por colchetes [ ]?','Qual destas opções representa uma lista em Python?');
UPDATE public.perguntas SET enunciado='Qual é a diferença entre uma lista e uma tupla?', alternativa_a='Só a lista aceita números', alternativa_b='A lista pode ser alterada; a tupla é imutável', alternativa_c='A tupla usa colchetes', alternativa_d='Listas não aceitam repetidos', correta='B', dificuldade='media', fonte='https://docs.python.org/3/library/stdtypes.html#sequence-types-list-tuple-range' WHERE enunciado IN ('Qual é a principal diferença entre uma lista e uma tupla em Python?','Qual é a diferença entre uma lista e uma tupla?');
UPDATE public.perguntas SET enunciado='Qual é o resultado de len([10, 20, 30])?', alternativa_a='3', alternativa_b='2', alternativa_c='30', alternativa_d='60', correta='A', dificuldade='media', fonte='https://docs.python.org/3/library/functions.html#len' WHERE enunciado IN ('Qual biblioteca em Python é amplamente utilizada para manipulação e análise de dados em tabelas (DataFrames)?','Qual é o resultado de len([10, 20, 30])?');
UPDATE public.perguntas SET enunciado='Quais valores são percorridos por for i in range(3)?', alternativa_a='1, 2, 3', alternativa_b='0, 1, 2', alternativa_c='0, 1, 2, 3', alternativa_d='Somente 3', correta='B', dificuldade='media', fonte='https://docs.python.org/3/tutorial/controlflow.html#the-range-function' WHERE enunciado IN ('No aprendizado de máquina supervisionado, qual é o papel do conjunto de dados de treino?','Quais valores são percorridos por for i in range(3)?');
UPDATE public.perguntas SET enunciado='Se notas = {"Ana": 5}, qual é o resultado de notas["Ana"]?', alternativa_a='"Ana"', alternativa_b='0', alternativa_c='5', alternativa_d='Erro sempre', correta='C', dificuldade='media', fonte='https://docs.python.org/3/tutorial/datastructures.html#dictionaries' WHERE enunciado IN ('Qual método de dicionário em Python retorna o valor de uma chave sem disparar KeyError se ela não existir?','Se notas = {"Ana": 5}, qual é o resultado de notas["Ana"]?');
UPDATE public.perguntas SET enunciado='Depois de numeros = [1, 2] e numeros.append(3), como fica a lista?', alternativa_a='[1, 2, 3]', alternativa_b='[3]', alternativa_c='[3, 1, 2]', alternativa_d='[1, 2]', correta='A', dificuldade='media', fonte='https://docs.python.org/3/tutorial/datastructures.html' WHERE enunciado IN ('O que é o fenômeno de Overfitting (sobreajuste) em modelos de Machine Learning?','Depois de numeros = [1, 2] e numeros.append(3), como fica a lista?');
UPDATE public.perguntas SET enunciado='Qual estrutura captura e trata um erro em Python?', alternativa_a='try ... catch', alternativa_b='try ... except', alternativa_c='if ... error', alternativa_d='for ... error', correta='B', dificuldade='media', fonte='https://docs.python.org/3/reference/compound_stmts.html#the-try-statement' WHERE enunciado IN ('Qual bloco é utilizado em Python para capturar e tratar exceções durante a execução?','Qual estrutura captura e trata um erro em Python?');
UPDATE public.perguntas SET enunciado='Considere a função:
def dobro(x):
    return x * 2
Qual é o resultado de dobro(4)?', alternativa_a='4', alternativa_b='8', alternativa_c='6', alternativa_d='2', correta='B', dificuldade='dificil', fonte='https://docs.python.org/3/tutorial/controlflow.html#defining-functions' WHERE enunciado IN ('Qual arquitetura apresentada no artigo "Attention Is All You Need" (2017) é baseada em mecanismos de atenção?','Considere a função:
def dobro(x):
    return x * 2
Qual é o resultado de dobro(4)?');
UPDATE public.perguntas SET enunciado='Qual valor fica em total?
total = 0
for n in range(1, 4):
    total = total + n', alternativa_a='6', alternativa_b='4', alternativa_c='10', alternativa_d='3', correta='A', dificuldade='dificil', fonte='https://docs.python.org/3/tutorial/controlflow.html#the-range-function' WHERE enunciado IN ('Em Python, o que caracteriza uma função geradora (generator function)?','Qual valor fica em total?
total = 0
for n in range(1, 4):
    total = total + n');
UPDATE public.perguntas SET enunciado='Se numeros = [10, 20, 30], quanto vale numeros[1] + numeros[2]?', alternativa_a='30', alternativa_b='50', alternativa_c='40', alternativa_d='60', correta='B', dificuldade='dificil', fonte='https://docs.python.org/3/tutorial/datastructures.html' WHERE enunciado IN ('Em uma compilação de CPython com GIL habilitado, qual é o efeito do Global Interpreter Lock?','Se numeros = [10, 20, 30], quanto vale numeros[1] + numeros[2]?');
UPDATE public.perguntas SET enunciado='Quantos números pares há na lista [1, 2, 3, 4]?
Dica: n % 2 == 0 verifica se n é par.', alternativa_a='1', alternativa_b='2', alternativa_c='3', alternativa_d='4', correta='B', dificuldade='dificil', fonte='https://docs.python.org/3/tutorial/controlflow.html' WHERE enunciado IN ('No treinamento de redes neurais profundas, qual problema ocorre quando os gradientes diminuem exponencialmente nas camadas iniciais?','Quantos números pares há na lista [1, 2, 3, 4]?
Dica: n % 2 == 0 verifica se n é par.');
UPDATE public.perguntas SET enunciado='Se pontos = {"Ana": 10}, qual é o resultado de pontos.get("Bia", 0)?', alternativa_a='10', alternativa_b='"Bia"', alternativa_c='0', alternativa_d='KeyError', correta='C', dificuldade='dificil', fonte='https://docs.python.org/3/library/stdtypes.html#dict.get' WHERE enunciado IN ('Qual é a complexidade média de tempo para verificar se uma chave existe em um dicionário (dict) em Python?','Se pontos = {"Ana": 10}, qual é o resultado de pontos.get("Bia", 0)?');
UPDATE public.perguntas SET enunciado='Considere:
def somar(a, b):
    return a + b
Qual é o resultado de somar(2, 3) * 2?', alternativa_a='10', alternativa_b='7', alternativa_c='5', alternativa_d='12', correta='A', dificuldade='dificil', fonte='https://docs.python.org/3/tutorial/controlflow.html#defining-functions' WHERE enunciado IN ('Qual técnica é usada para enriquecer o contexto de um LLM com dados externos recuperados de um banco vetorial antes de gerar a resposta?','Considere:
def somar(a, b):
    return a + b
Qual é o resultado de somar(2, 3) * 2?');
COMMIT;
